 <div class="plan-scroll"><table class="plan-table"><thead><tr><th class="plan-frozen">Fonte / compromisso ${info('Clique no lápis ao lado do nome para editar ou excluir o cadastro inteiro.')}</th>${months.map(mm=>`<th>${e(prettyMonth(mm))}</th>`).join('')}</tr></thead><tbody>
 ${monthPlanTable('income',months)}${monthPlanTable('benefit',months)}${monthPlanTable('expense',months)}${planDebtRows(months)}
 <tr class="plan-group"><th colspan="13">ALOCAR PARA RESERVA E SONHOS ${info('Este valor é destinado a guardar, como para construir a casa ou montar reserva. Reduz a disponibilidade projetada, mas não é despesa consumida.')}</th></tr>
 <tr class="plan-item plan-savings"><th scope="row"><span>Quanto desejo guardar</span><small>Reserva, cofrinhos, metas</small></th>${months.map(mm=>`<td><input class="plan-input" title="Valor que desejo separar em ${e(prettyMonth(mm))}" aria-label="Dinheiro para guardar em ${e(prettyMonth(mm))}" type="number" min="0" step="0.01" data-plan-kind="savings" data-month="${mm}" value="${plannedSavings(mm)}" /></td>`).join('')}</tr>
 <tr class="plan-group plan-results"><th colspan="13">RESULTADO POR MÊS</th></tr>
 ${planTotalsRows(months)}</tbody></table></div>
