function planTotalsRows(months){const rows=[['Receitas','income'],['Despesas + parcelas','expense'],['Guardar','saving'],['Disponível no mês','net'],['Acumulado teórico','cumulative']];const data=projected();return rows.map(([label,key])=>`<tr class="plan-total"><th>${label}</th>${data.map(x=>`<td class="${(key==='net'||key==='cumulative')&&x[key]<0?'negative':''}">${money(x[key])}</td>`).join('')}</tr>`).join('')}
function recommendationCards(){return `<div class="recommendations">${recommendations().map((a,i)=>`<div class="rec-card"><div class="rec-icon" title="${e(a.short)}">${a.ico}</div><span class="rec-rank">OPÇÃO ${i+1}</span><strong>${e(a.title)}</strong><p>${e(a.short)}</p><button data-action="recommendation" data-rec="${i}" title="Entenda por que essa ação foi sugerida">Entender a recomendação →</button></div>`).join('')}</div>`}
function refreshPlannerLive(){if(page!=='planner')return;const a=$('#plannerSummary');if(a)a.innerHTML=plannerSummary();const b=$('#plannerRecommendations');if(b)b.innerHTML=recommendationCards();document.querySelectorAll('.plan-total').forEach((row,i)=>{const key=['income','expense','saving','net','cumulative'][i];if(!key)return;const arr=projected();row.querySelectorAll('td').forEach((td,j)=>{td.textContent=money(arr[j][key]);td.classList.toggle('negative',(key==='net'||key==='cumulative')&&arr[j][key]<0)})})}
