function closeModal(){ $('#modalBackdrop').classList.add('hidden'); $('#modal').innerHTML='';modalHandler=null}
function modal(title,desc,body,footer='',onSubmit=null){
 modalHandler=onSubmit;
 const defaultFooter='<button class="secondary" type="button" data-modal-close>Cancelar</button><button class="primary" type="submit">Salvar</button>';
 let content=onSubmit?`<form id="modalForm">${body}<div class="modal-foot">${footer||defaultFooter}</div></form>`:body+(footer?`<div class="modal-foot">${footer}</div>`:'');
 $('#modal').innerHTML=`<div class="modal-head"><div><h2>${e(title)}</h2><p>${e(desc)}</p></div><button class="x-btn" type="button" data-modal-close aria-label="Fechar">×</button></div>${content}`;
 $('#modalBackdrop').classList.remove('hidden');
 let f=$('#modalForm');if(f)f.onsubmit=ev=>{ev.preventDefault();if(privacyEnabled){toast('Mostre os valores antes de salvar alterações.',true);return;}let data=Object.fromEntries(new FormData(f).entries());if(modalHandler?.(data)===false)return;closeModal();persist();render()};
 applyPrivacyUI();if(!privacyEnabled)$('#modalBackdrop').querySelector('input:not([type=hidden]),select')?.focus()
}
function field(label,name,value='',opts=''){return `<label class="form-field">${e(label)}<input name="${e(name)}" value="${e(value)}" ${opts} /></label>`}
function selectField(label,name,value,options){return `<label class="form-field">${e(label)}<select name="${e(name)}">${options.map(o=>`<option value="${e(o[0])}" ${String(value)===String(o[0])?'selected':''}>${e(o[1])}</option>`).join('')}</select></label>`}
function formFooter(saveLabel='Salvar'){return `<button class="secondary" type="button" data-modal-close>Cancelar</button><button class="primary" type="submit">${e(saveLabel)}</button>`}
function historyModal(reference=null){const old=state.history.find(x=>x.month===reference),o=old||{month:month,income:0,expenses:0,source:'Cadastro manual'};
 modal(old?'Editar histórico do mês':'Registrar histórico do mês','Informe as receitas e despesas realizadas do período encerrado. Isto não modifica a previsão futura.',`<div class="field-grid">${field('Mês de referência','month',o.month,'type="month" required')}${field('Receitas reais ou totais do mês (R$)','income',o.income,'type="number" min="0" step="0.01" required')}${field('Despesas reais ou totais do mês (R$)','expenses',o.expenses,'type="number" min="0" step="0.01" required')}${field('Origem / observação','source',o.source||'Manual','type="text" maxlength="100"')}</div><div class="notice">Não cadastre os mesmos pagamentos como valores realizados e previsões futuras. Este histórico serve para análise de meses encerrados.</div>`,formFooter('Salvar histórico'),f=>{if(!/^\d{4}-\d{2}$/.test(f.month))return toast('Mês inválido.',true),false;const existing=state.history.find(x=>x.month===f.month&&x!==old);if(existing)return toast('Já existe histórico para este mês. Edite o registro existente.',true),false;const item={month:f.month,income:safeAmount(f.income),expenses:safeAmount(f.expenses),source:f.source.trim()||'Manual'};if(old)Object.assign(old,item);else state.history.push(item);return true});}
